  "logic": "class Component extends DCLogic {\n  pillar() {\n    const PILLARS = {\n      standaard: { bg: \"#3D5AFE\", text: \"#ffffff\", sub: \"#060228\", mark: \"rgba(255,255,255,.16)\", ctaBg: \"#060228\", ctaText: \"#ffffff\" },\n      jump:      { bg: \"#49FF9F\", text: \"#060228\", sub: \"#2F7E4D\", mark: \"rgba(6,2,40,.06)\",  ctaBg: \"#2F7E4D\", ctaText: \"#ffffff\" },\n      marketing: { bg: \"#FFCC00\", text: \"#060228\", sub: \"#C25100\", mark: \"rgba(6,2,40,.06)\",  ctaBg: \"#060228\", ctaText: \"#ffffff\" },\n      content:   { bg: \"#00FFE6\", text: \"#060228\", sub: \"#008B8B\", mark: \"rgba(6,2,40,.06)\",  ctaBg: \"#060228\", ctaText: \"#ffffff\" },\n      productie: { bg: \"#FC06E5\", text: \"#060228\", sub: \"#7B1FA2\", mark: \"rgba(6,2,40,.06)\",  ctaBg: \"#060228\", ctaText: \"#ffffff\" },\n      navy:      { bg: \"#060228\", text: \"#ffffff\", sub: \"#49FF9F\", mark: \"rgba(255,255,255,.07)\", ctaBg: \"#3D5AFE\", ctaText: \"#ffffff\" },\n    };\n    return PILLARS[this.props.pillar] || PILLARS.standaard;\n  }\n  applyVars() {\n    const p = this.pillar(), r = window.__bytRoot.style;\n    r.setProperty(\"--bg\", p.bg); r.setProperty(\"--text\", p.text); r.setProperty(\"--sub\", p.sub);\n    r.setProperty(\"--mark\", p.mark); r.setProperty(\"--cta-bg\", p.ctaBg); r.setProperty(\"--cta-text\", p.ctaText);\n  }\n  componentDidMount() { this.applyVars(); }\n  componentDidUpdate() { this.applyVars(); }\n  renderVals() {\n    return {\n      quote: this.props.quote ?? \"Los van de kans voelt het vooral als bevestiging dat we op de goede weg zitten en dat wat we doen verder kan reiken dan landsgrenzen.\",\n      author: this.props.author ?? \"Patrick van Mil\",\n      cta: this.props.cta ?? \"Lees het hele artikel op Substack\",\n    };\n  }\n}",
