  "logic": "class Component extends DCLogic {\n  pillar() {\n    const PILLARS = {\n      standaard: { bg: \"#060228\", mark: \"#ffffff\", title: \"#ffffff\", pill: \"rgba(255,255,255,.16)\" },\n      jump:      { bg: \"#49FF9F\", mark: \"#2F7E4D\", title: \"#060228\", pill: \"rgba(6,2,40,.10)\" },\n      marketing: { bg: \"#FFCC00\", mark: \"#C25100\", title: \"#060228\", pill: \"rgba(6,2,40,.10)\" },\n      content:   { bg: \"#00FFE6\", mark: \"#008B8B\", title: \"#060228\", pill: \"rgba(6,2,40,.10)\" },\n      productie: { bg: \"#FC06E5\", mark: \"#7B1FA2\", title: \"#060228\", pill: \"rgba(6,2,40,.10)\" },\n      blauw:     { bg: \"#3D5AFE\", mark: \"#060228\", title: \"#ffffff\", pill: \"rgba(255,255,255,.16)\" },\n    };\n    return PILLARS[this.props.pillar] || PILLARS.standaard;\n  }\n  applyVars() {\n    const p = this.pillar(), r = window.__bytRoot.style;\n    r.setProperty(\"--bg\", p.bg); r.setProperty(\"--mark\", p.mark);\n    r.setProperty(\"--title\", p.title); r.setProperty(\"--pill-bg\", p.pill);\n  }\n  componentDidMount() { this.applyVars(); }\n  componentDidUpdate() { this.applyVars(); }\n  renderVals() {\n    return {\n      eyebrow: this.props.eyebrow ?? \"BINNENKORT\",\n      title: this.props.title ?? \"Alle sporters zijn helden\",\n    };\n  }\n}",
